import type {
  BackgroundCommand,
  CameraCommand,
  GenerationId,
  HardwareGenerationProfile,
  LightCommand,
  MaterialCommand,
  MeshCommand,
  RenderFrame,
} from '@console-chaos/engine';

import type { ViewContext } from './context.js';
import {
  CAR_LAMP_COLORS,
  carLampsFor,
  carLampsVisible,
  carModelFor,
  carModelScale,
  carTextureFor,
  carTransform,
  carWheelAsset,
  carWheelPhase,
} from './shared/car-model.js';
import { hidesPlayerCar, resolveCameraView, viewCamera } from './shared/camera.js';
import { cockpitSprites } from './shared/cockpit.js';
import { ENVIRONMENT_MAP, SKYLINE, SUN_DIRECTION, equirectU } from './shared/environment.js';
import { pushHud } from './shared/hud.js';
import { defaultMinimapRect, pushMinimap } from './shared/minimap.js';
import { sceneryFor } from '../sim/scenery.js';
import { tyreWallDrawDistance, tyreWallMeshes } from './shared/scenery-mesh.js';
import { sceneryBillboardAtlasFor, sceneryBillboards } from './shared/scenery-sprite.js';
import {
  trackMeshLodFor,
  trackSectorAsset,
  trackSurfaceTexture,
  visibleSectors,
} from './shared/track-mesh.js';
import {
  tunnelAsset,
  tunnelBlendAt,
  tunnelLampAsset,
  tunnelTexture,
  tunnelVisible,
} from './shared/tunnel.js';
import {
  ENTRANT_COLORS,
  PLAYER_ENTRANT,
  SKY_COLORS,
  generationValue,
  mixColor,
  mixNumber,
} from './shared/variants.js';

/**
 * 第4世代（PS2）— 深度バッファと動的ライトのある 3D（実装計画 §3.4）。
 *
 * レンダラーが自動でやること: 640×448 / linear フィルタ / 頂点量子化なし /
 * perspective UV / component の CRT。**第3世代と同じ車・同じコース定義・同じカメラ**を
 * 通しても別物に見えることが、この世代の主張になる。ゲーム側が足すのは 4 つ。
 *
 * 1. **映り込み** — `environmentTexture` に正距円筒の環境マップ。車の向きに応じて
 *    景色が車体を流れる。4 世代でこの世代だけの表現（§6.1 第4世代基準 1）。
 * 2. **空との一致** — 遠景の層に、同じ環境マップから焼いた地平線の帯を貼る。
 *    水平線の位置と方位を実際のカメラから求めるので、映り込みと画面の空が揃う（基準 2）。
 * 3. **動的ライト** — 環境マップの太陽と同じ向きの directional、空の色の ambient、
 *    そして落ち影を生む点光源（基準 3）。
 * 4. **前後関係** — 深度バッファがあるので ordering table も三角形ソートも要らない。
 *    第3世代の `orderTableIndex` / `polygonSortRange` がここには 1 つも無いことが、
 *    そのままハードウェアの差になっている。
 */

/** フォグ密度 [1/m]。exp(-d·density) なので 100 m で 67%・300 m で 96% 霞む */
const FOG_DENSITY = 0.011;

/**
 * トンネルの中のフォグ密度 [1/m]（実装計画 8-9）。
 *
 * 外より**薄くする**。フォグ色は空の色から引いているので、密度をそのままにすると
 * 20 m 先の内壁まで空色に霞んで「霧のトンネル」になる。逆に薄くしておくと、
 * 坑口の外だけが明るく霞み、出口の明かりが強く出る。
 */
const TUNNEL_FOG_DENSITY = 0.004;

/**
 * トンネルの中の照明（実装計画 8-9）。
 *
 * レンダラーは**最も強い点光源 1 つ**しか読まないので、灯具を並べて置くことはできない。
 * 代わりに次の 3 つを `tunnelBlendAt()` で混ぜる。
 *
 * 1. 環境光を暗い青灰へ落とす（天井が空を塞いでいる状態）
 * 2. 太陽（directional）を 0 近くまで落とす
 * 3. 自機の上の点光源を、白からナトリウム灯の橙へ寄せて強くする
 *
 * **影を落とす光源も 3 番と同じ 1 つ**なので、トンネルの中では車の影が
 * 天井の灯具から落ちる影に変わる。落ち影の倍率は高さで決まる（`KEY_LIGHT`）ので、
 * 灯具の高さまで下げると影が大きく薄くなる — それがそのままトンネルらしさになる。
 */
const TUNNEL_AMBIENT = { color: '#39434f', intensity: 1 } as const;
const TUNNEL_SUN = { color: '#4a4a48', intensity: 1 } as const;
const TUNNEL_LIGHT = { height: 6, radius: 26, color: '#ffb257', intensity: 0.85 } as const;

/**
 * トンネルの躯体と灯具のマテリアル。
 *
 * 躯体は路面より暗く焼いてある（`ambient` を落とす）。**外から見ても中が暗い**
 * ことが要るからで、フレームの照明だけで暗くすると、坑口をくぐった瞬間に
 * 内壁の明るさが跳ねる。灯具は逆に `ambient` を 1 より大きく採る —
 * シェーダは `uAmbient = material.ambient × 環境光` を 1 で頭打ちにするので、
 * 環境光が 0.22 まで落ちるトンネルの中でも灯具だけは白く残る。
 */
const TUNNEL_SURFACE = { ambient: 0.5, diffuse: 0.4 } as const;
const TUNNEL_LAMP_SURFACE = { ambient: 4, diffuse: 0 } as const;

/** トンネルを積み始める距離 [m]。躯体は 1 つのメッシュなので粒度はこれで足りる */
const TUNNEL_DRAW_DISTANCE = 320;

/**
 * 映り込みの強さ。シェーダは
 * `color·(1−k) + k·min(color·0.55 + env·0.65, 1)` という合成なので、
 * 0.35 でも空の青が車体へはっきり乗る。上げると塗装の色が飛ぶ。
 */
const ENVIRONMENT_STRENGTH = 0.35;

/**
 * ライティング。`uAmbient = material.ambient × (ambient ライトの色 × 強さ)` で、
 * そこへ `directional の色 × diffuse × lambert` が足される。
 * 上向きの面で合計がほぼ 1 になるように選んである。
 */
const AMBIENT_LIGHT = { color: '#9ab4d2', intensity: 1 } as const;
const SUN_LIGHT = { color: '#fff2d8', intensity: 1 } as const;
const SURFACE = { ambient: 0.75, diffuse: 0.55 } as const;

/**
 * 落ち影を生む点光源（実装計画 §3.4）。
 *
 * エンジンは**最も強い点光源 1 つ**から、`castShadow` を持つメッシュの影を
 * `groundY` の高さへ落とす。倍率は `高さ /(高さ − 車の高さ)` で、影の大きさに掛かり
 * 濃さにはその逆数が掛かる。低く置くと影が巨大化して薄まり、しかも遠くの車ほど
 * 影が横へ流れる（影は光源から見た投影なので、`(車 − 光源) × 倍率` だけずれる）。
 * **高く置くほど倍率が 1 に近づく**ので、40 m 上に置いて倍率 1.006 に収めている。
 *
 * 半径は「高さより少しだけ大きい」程度にする。点光源は距離減衰つきの照明でもあり、
 * 半径を広げると自機のまわりだけが明るく浮く。
 */
const KEY_LIGHT = { height: 40, radius: 44, color: '#fff2d8', intensity: 0.3 } as const;

/**
 * 落ち影の半径 [m]。**影を落とすためだけの、描かれないメッシュ**に与える。
 *
 * 影の四角形の大きさは `transform.scale` から作られる。車のメッシュに与えれば
 * 車体そのものが歪むので、代わりに影専用のメッシュを 1 台につき 1 つ積む。
 * `SHADOW_MATERIAL` が `colorFactor` を透明にして `alphaCutoff` で全画素を捨てるため、
 * 色は 1 画素も描かれず、影の投影にだけ現れる。ジオメトリは事前確保済みの quad
 * （2 三角形）なので、費用はドローコール 1 つぶんしかない。
 *
 * 四角形は**回転しない**（影の行列は平行移動と拡大だけ）ので、正方形に採る。
 * 一辺は**車体の倍率と一緒に伸びる**（11-5）。素のモデルの footprint 1.9 × 0.88 m に
 * 対して 1.0 m 角だったので、実寸（4.22 × 1.95 m）では 2.21 m 角になる。
 * どの向きでも車体の下からはみ出す量が最小になる大きさ（車幅より少しだけ広いのは
 * タイヤのぶん）という選び方はそのまま保たれる。
 *
 * **全長からは採らない。** 4.2 m 角にすると回転しない四角形が車体の左右へ
 * 1.1 m ずつはみ出し、影が車の 2 倍の幅で路面に落ちる。
 */
const SHADOW_HALF_RATIO = 0.5;

/**
 * テールランプのマテリアル（12-7）。トンネルの灯具と同じで、`ambient` を 1 より
 * 大きく採って照明に関係なく明るく残す（`diffuse` は 0）。**映り込みは掛けない** —
 * 光っている面に空が映ると濁る。引くテクセルは塗装テクスチャの明るい無彩色 1 点で、
 * 灯火の色は `MeshCommand.color` の乗算だけで決まる。
 */
const LAMP_SURFACE = { ambient: 4, diffuse: 0 } as const;

/**
 * ライバルを描く上限距離 [m]。フォグが 95% を超えるとほぼ背景と区別が付かない。
 * 描画するセクターの前方保証（310 m）の内側でもある。
 */
const CAR_DRAW_DISTANCE = 280;

/**
 * `asset` 付きメッシュの `geometry` は参照されないが、`quad` の `halfSize` だけは
 * モデル行列へ掛かる。単位のまま置く。
 */
const TRACK_GEOMETRY = { kind: 'quad', halfSize: [1, 1] } as const;

export function buildGen4View(frame: RenderFrame, context: ViewContext): void {
  const { generation, profile, state, display } = context;
  const track = state.track;
  const lod = trackMeshLodFor(generation);
  const carModel = carModelFor(generation);
  const player = display.cars[PLAYER_ENTRANT];
  if (!lod || !carModel || !player) return;

  // 視点は自分の世代にあるものへ落とす（8-5）。内装があるのはこの世代だけ
  const view = resolveCameraView(generation, context.cameraView ?? 'chase');
  const hidePlayer = hidesPlayerCar(view);
  const camera = viewCamera({ track, car: player, view });
  frame.camera = camera;

  // トンネルらしさ 0..1。照明もフォグも映り込みも、この 1 つの値から混ぜる（8-9）
  const inTunnel = tunnelBlendAt(track, player.s);

  for (const background of skylineBackgrounds(generation, profile, camera, inTunnel)) {
    frame.backgrounds.push(background);
  }

  // ── ライト。太陽の向きは環境マップの最輝点から実測した 1 つの定数で、
  // 映り込みに写っている太陽と陰影が食い違わない
  const playerWorld = track.toWorld(player.s, player.lateral);
  const keyHeight = mixNumber(KEY_LIGHT.height, TUNNEL_LIGHT.height, inTunnel);
  frame.lights.push(
    {
      id: `ambient-${generation}`,
      kind: 'ambient',
      position: [0, 0, 0],
      color: mixColor(AMBIENT_LIGHT.color, TUNNEL_AMBIENT.color, inTunnel),
      intensity: mixNumber(AMBIENT_LIGHT.intensity, TUNNEL_AMBIENT.intensity, inTunnel),
      radius: 0,
      generations: [generation],
    },
    {
      id: `sun-${generation}`,
      kind: 'directional',
      position: [0, 0, 0],
      direction: [...SUN_DIRECTION],
      // 天井が空を塞ぐぶんを色で表す。向きは変えない（出口の外はもとの太陽のまま）
      color: mixColor(SUN_LIGHT.color, TUNNEL_SUN.color, inTunnel),
      intensity: mixNumber(SUN_LIGHT.intensity, TUNNEL_SUN.intensity, inTunnel),
      radius: 0,
      generations: [generation],
    },
    {
      id: `key-${generation}`,
      kind: 'point',
      position: [playerWorld[0], playerWorld[1] + keyHeight, playerWorld[2]],
      color: mixColor(KEY_LIGHT.color, TUNNEL_LIGHT.color, inTunnel),
      intensity: mixNumber(KEY_LIGHT.intensity, TUNNEL_LIGHT.intensity, inTunnel),
      radius: mixNumber(KEY_LIGHT.radius, TUNNEL_LIGHT.radius, inTunnel),
      generations: [generation],
    } satisfies LightCommand,
  );

  // ── 路面。深度バッファがあるので、セクター分割は純粋に描画距離のカリングでしかない
  const trackMaterial: MaterialCommand = {
    id: `track-${generation}`,
    baseColorTexture: trackSurfaceTexture(lod),
    // レンダラーは UV 補正をプロファイル（`affineTexture`）から決める。ここは意図の記録
    uvMode: 'perspective',
    // 金網の網目を抜く（8-10）。路面・縁石・草地・壁の帯は全画素不透明なので、
    // 同じマテリアルで路面を描いても 1 画素も落ちない
    ...(lod.fenceHeight === null ? {} : { alphaCutoff: 0.5 }),
    ...SURFACE,
    generations: [generation],
  };
  frame.materials.push(trackMaterial);

  for (const sector of visibleSectors(lod, player.s, track.length)) {
    frame.meshes.push({
      id: `track-${generation}-${sector}`,
      geometry: TRACK_GEOMETRY,
      asset: trackSectorAsset(lod, sector),
      transform: { position: [0, 0, 0] },
      color: '#ffffff',
      material: trackMaterial.id,
      receiveShadow: true,
      generations: [generation],
    });
  }

  // ── トンネル（8-9）。位置が固定なので、区間へ近づいたときだけ 2 つ積む。
  // 躯体と灯具でマテリアルが違う（灯具は環境光が落ちても明るいまま）
  if (tunnelVisible(track, player.s, TUNNEL_DRAW_DISTANCE)) {
    const structure: MaterialCommand = {
      id: `tunnel-${generation}`,
      baseColorTexture: tunnelTexture(lod),
      uvMode: 'perspective',
      ...TUNNEL_SURFACE,
      generations: [generation],
    };
    const lamp: MaterialCommand = {
      id: `tunnel-lamp-${generation}`,
      baseColorTexture: tunnelTexture(lod),
      uvMode: 'perspective',
      ...TUNNEL_LAMP_SURFACE,
      generations: [generation],
    };
    frame.materials.push(structure, lamp);
    frame.meshes.push(
      {
        id: `tunnel-${generation}`,
        geometry: TRACK_GEOMETRY,
        asset: tunnelAsset(lod),
        transform: { position: [0, 0, 0] },
        color: '#ffffff',
        material: structure.id,
        receiveShadow: true,
        generations: [generation],
      },
      {
        id: `tunnel-lamp-${generation}`,
        geometry: TRACK_GEOMETRY,
        asset: tunnelLampAsset(lod),
        transform: { position: [0, 0, 0] },
        color: '#ffffff',
        material: lamp.id,
        generations: [generation],
      },
    );
  }

  // ── 車。塗装テクスチャは無彩色 1 枚を 8 台で共有し、車体色は乗算だけで決まる。
  // 映り込みはマテリアル側なので、8 台とも同じ環境マップが同じ強さで乗る
  const carMaterial: MaterialCommand = {
    id: `car-${generation}`,
    baseColorTexture: carTextureFor(generation),
    environmentTexture: ENVIRONMENT_MAP.url,
    // トンネルの中では映り込みを 1/4 まで落とす（8-9）。映り込む空がそこには無い。
    // **塗装が艶を失って出口でまた戻る**のが、この世代でしか出せない見え方になる
    environmentStrength: ENVIRONMENT_STRENGTH * mixNumber(1, 0.25, inTunnel),
    uvMode: 'perspective',
    ...SURFACE,
    generations: [generation],
  };
  frame.materials.push(carMaterial);

  // 灯火（12-7）。車体と違って環境マップを持たない 1 つだけのマテリアル
  const lampMaterial: MaterialCommand = {
    id: `car-lamp-${generation}`,
    baseColorTexture: carTextureFor(generation),
    uvMode: 'perspective',
    ...LAMP_SURFACE,
    generations: [generation],
  };
  const lamps = carLampsFor(generation);
  if (lamps) frame.materials.push(lampMaterial);

  // 影を落とすためだけのメッシュが使うマテリアル。全画素を捨てる（`SHADOW_HALF_RATIO`）
  const shadowMaterial: MaterialCommand = {
    id: `car-shadow-${generation}`,
    baseColorTexture: carTextureFor(generation),
    colorFactor: [0, 0, 0, 0],
    alphaCutoff: 1,
    generations: [generation],
  };
  frame.materials.push(shadowMaterial);

  const shadowHalf = SHADOW_HALF_RATIO * carModelScale(generation);

  for (const car of display.cars) {
    // 車内からの視点では自機を積まない。**影専用メッシュも積まない** —
    // 車体が無いのに影だけが路面へ落ちていたら、そちらのほうが目立つ
    if (hidePlayer && car.entrant === PLAYER_ENTRANT) continue;
    const ground = track.toWorld(car.s, car.lateral);
    const away = Math.hypot(
      ground[0] - camera.position[0],
      ground[1] - camera.position[1],
      ground[2] - camera.position[2],
    );
    if (car.entrant !== PLAYER_ENTRANT && away > CAR_DRAW_DISTANCE) continue;

    const transform = carTransform(track, car, generation);
    frame.meshes.push({
      id: `car-${generation}-${car.entrant}`,
      geometry: TRACK_GEOMETRY,
      asset: carModel.asset,
      transform,
      color: ENTRANT_COLORS[car.entrant % ENTRANT_COLORS.length] ?? '#ffffff',
      material: carMaterial.id,
      generations: [generation],
    } satisfies MeshCommand);

    // ── 車輪（12-7）。車体 GLB から切り離してあるので**必ず一緒に積む**。
    // 位相を焼いた 8 枚から走った距離で 1 枚を選ぶ。深度バッファがあるので
    // 積む順は問わない（第3世代がここで順序を作っているのと対になる）。
    // 車体色は掛けない — 塗装テクスチャは無彩色なので、白のままがゴムと金属の色になる
    frame.meshes.push({
      id: `car-wheels-${generation}-${car.entrant}`,
      geometry: TRACK_GEOMETRY,
      asset: carWheelAsset(generation, carWheelPhase(generation, car.s)),
      transform,
      color: '#ffffff',
      material: carMaterial.id,
      generations: [generation],
    } satisfies MeshCommand);

    // ── テールランプ（12-7）。後ろを向いた一枚面なので、前から見た車では
    // 背面カリングで消える。明るさはブレーキの踏み量で混ぜる
    if (lamps && carLampsVisible(track, car, camera.position)) {
      frame.meshes.push({
        id: `car-lamp-${generation}-${car.entrant}`,
        geometry: TRACK_GEOMETRY,
        asset: lamps.asset,
        transform,
        color: mixColor(CAR_LAMP_COLORS.idle, CAR_LAMP_COLORS.brake, car.brakeInput),
        material: lampMaterial.id,
        generations: [generation],
      } satisfies MeshCommand);
    }

    frame.meshes.push({
      id: `car-shadow-${generation}-${car.entrant}`,
      geometry: TRACK_GEOMETRY,
      transform: { position: transform.position, scale: [shadowHalf, 1, shadowHalf] },
      color: '#000000',
      material: shadowMaterial.id,
      castShadow: true,
      groundY: ground[1],
      generations: [generation],
    } satisfies MeshCommand);
  }

  // ── 背景オブジェクト（8-6）。壁はコースメッシュへ焼き込んであるので、
  // ここで積むのは木（ビルボード）とタイヤフェンス（専用メッシュ）だけ。
  // **描画順の指定は 1 つも書かない** — 深度バッファがあるのだから要らない。
  // それがそのまま第3世代との差になる（§3.4）
  const objects = sceneryFor(track);
  const tyreDistance = tyreWallDrawDistance(generation);
  if (tyreDistance !== null) {
    for (const mesh of tyreWallMeshes({
      generation,
      track,
      objects,
      material: trackMaterial.id,
      camera: camera.position,
      drawDistance: tyreDistance,
    })) {
      frame.meshes.push(mesh);
    }
  }

  const billboards = sceneryBillboardAtlasFor(generation);
  if (billboards) {
    for (const sprite of sceneryBillboards({
      generation,
      track,
      objects,
      atlas: billboards,
      camera: camera.position,
      // 深度バッファに任せる。不透明扱い（`alphaCutoff` で抜く）で積む
      depthWrite: true,
    })) {
      frame.sprites.push(sprite);
    }
  }

  // ── 内装（8-5）。カメラは `windshield` と同じで、被せる 1 枚だけが違う。
  // HUD とミニマップより先に積むので、数字は内装の上に出る
  if (view === 'cockpit') {
    for (const sprite of cockpitSprites({ generation, profile, car: player })) {
      frame.sprites.push(sprite);
    }
  }

  pushMinimap(frame, {
    generation,
    profile,
    track,
    cars: display.cars,
    rect: defaultMinimapRect(generation, profile),
    frameIndex: display.frameIndex,
  });

  // HUD は最後 ＝ 最前面。深度バッファがあってもスクリーン空間スプライトは
  // シーンの末尾へ合成されるので、積んだ順がそのまま重ね順になる
  pushHud(frame, { generation, profile, display, screen: context.screen });
}

/** カメラの向き。方位はワールドの `atan2(z, x)`、ピッチは見下ろしが負 */
export function cameraAngles(camera: CameraCommand): { azimuth: number; pitch: number } {
  const dx = camera.target[0] - camera.position[0];
  const dy = camera.target[1] - camera.position[1];
  const dz = camera.target[2] - camera.position[2];
  return { azimuth: Math.atan2(dz, dx), pitch: Math.atan2(dy, Math.hypot(dx, dz)) };
}

/**
 * 空の階調 ＋ 環境マップの地平線の帯（実装計画 §3.4 / §6.1 第4世代基準 2）。
 *
 * `BackgroundCommand.parallax` はレンダラーが読まないので、視差は自分で `offset` へ
 * 畳み込む（第1・第2世代の `backdrop.ts` と同じ事情）。違うのは、こちらは
 * **視差の量が推測ではなく決まっている**ことである。帯は 360° を 1 枚に収めた
 * 正距円筒の切り出しなので、画角ぶんの U を覗き、視線の方位ぶんずらせばよい。
 * 映り込みが引く U とまったく同じ式（`equirectU`）を通るため、車体に映る景色と
 * 画面の空が必ず一致する。
 *
 * 縦は水平線の位置だけを合わせる。層は画面に平らに貼られるので仰角と行の対応は
 * 本来 tan で曲がるが、帯を ±50° と広く採って画面を覆いきらせ、ずれは絵の無い空へ
 * 逃がしてある（`shared/environment.ts` の `SKYLINE`）。
 */
export function skylineBackgrounds(
  generation: GenerationId,
  profile: HardwareGenerationProfile,
  camera: CameraCommand,
  /** トンネルらしさ 0..1。フォグ密度だけを混ぜる（8-9） */
  inTunnel = 0,
): BackgroundCommand[] {
  const width = profile.video.internalWidth;
  const height = profile.video.internalHeight;
  const sky = generationValue(SKY_COLORS, generation);

  const { azimuth, pitch } = cameraAngles(camera);
  const halfTan = Math.tan((((camera.fovDegrees ?? 55) * Math.PI) / 180) / 2);
  // 画面中央付近では 1 rad ＝ この画素数。水平線はカメラのほぼ正面にあるので十分正確
  const pixelsPerRadian = height / 2 / halfTan;
  const horizonRow = height / 2 + pitch * pixelsPerRadian;
  const rowTop = horizonRow - SKYLINE.topAngle * pixelsPerRadian;
  const rowBottom = horizonRow - SKYLINE.bottomAngle * pixelsPerRadian;

  // 画面が覆う水平画角。縦画角と内部解像度の縦横比から出る
  const horizontalFov = 2 * Math.atan((halfTan * width) / height);
  const repeat = horizontalFov / (2 * Math.PI);

  return [
    // テクスチャを持たない背景が空の階調とフォグ色を決める。帯が画面を覆うので
    // 階調が見えることは無いが、フォグ色はここでしか指定できない。
    // **色はトンネルの中でも変えない** — 変えると坑口の外の空まで暗くなり、
    // 出口の明かりが消える（フォグ色は空の色と 1 つの値を共有している）
    {
      color: sky.bottom,
      secondaryColor: sky.top,
      fogDensity: mixNumber(FOG_DENSITY, TUNNEL_FOG_DENSITY, inTunnel),
      generations: [generation],
    },
    {
      color: sky.bottom,
      texture: SKYLINE.url,
      repeat: [repeat, 1],
      offset: [equirectU(azimuth) - repeat / 2, 0],
      placement: {
        bottom: (height - rowBottom) / height,
        height: (rowBottom - rowTop) / height,
      },
      generations: [generation],
    },
  ];
}
